#!/usr/bin/env node
import {
  buildScaleComparison,
  getScaleWarnings,
  resolveScaleFactor
} from "./chunk-E4B6DFAN.js";
import {
  resolveStockFromConfig
} from "./chunk-EXIXW6Q5.js";
import "./chunk-JCFG34DV.js";
import {
  runPipeline
} from "./chunk-XW73TKNN.js";
import "./chunk-4MSISIPG.js";
import {
  fmtNumber
} from "./chunk-NDIRV4C7.js";
import {
  reportRejectedIngredients
} from "./chunk-4A6RJKSG.js";
import {
  version
} from "./chunk-37DSMZOH.js";
import {
  loadDbSafe
} from "./chunk-J5CTY35W.js";
import {
  loadConfig
} from "./chunk-LYQHWV53.js";
import "./chunk-IWNALT6P.js";
import "./chunk-5APUWLPI.js";
import {
  ExitCode,
  reportError
} from "./chunk-IXNX2GX7.js";

// src/commands/scale.ts
import { defineCommand } from "citty";
import { resolve } from "path";
import { log as log2, spinner } from "@clack/prompts";

// src/ui/scaler.ts
import chalk from "chalk";
import { log } from "@clack/prompts";
import { isCoarseUnit } from "@gram-lang/i18n";
function fmtQty(qty, unit) {
  const decimals = isCoarseUnit(unit) ? 1 : 2;
  const rounded = Math.abs(qty - Math.round(qty)) < 5e-3 ? Math.round(qty) : parseFloat(qty.toFixed(decimals));
  return unit ? `${fmtNumber(rounded, decimals)}${unit}` : fmtNumber(rounded, 1);
}
function renderScaleResult(title, factor, items, warnings) {
  const factorStr = factor === Math.round(factor) ? `\xD7${factor}` : `\xD7${factor.toFixed(2)}`;
  const header = title ? `${title} \u2014 ${factorStr}` : factorStr;
  const scalable = items.filter((i) => !i.nonScalable);
  const nonScalable = items.filter((i) => i.nonScalable);
  console.log();
  console.log(`  ${chalk.bold(header)}`);
  console.log();
  const COL_NAME = 22;
  const COL_QTY = 11;
  if (scalable.length > 0) {
    console.log(
      `  ${"Ingredient".padEnd(COL_NAME)} ${chalk.dim("Original".padStart(COL_QTY))} ${chalk.dim("Scaled".padStart(COL_QTY))}`
    );
    console.log(`  ${"\u2500".repeat(COL_NAME + COL_QTY * 2 + 3)}`);
    for (const item of scalable) {
      const name = (item.name || item.id).slice(0, COL_NAME).padEnd(COL_NAME);
      const orig = chalk.dim(
        fmtQty(item.originalQty, item.unit ?? null).padStart(COL_QTY)
      );
      const scaled = chalk.green(
        fmtQty(item.scaledQty, item.unit ?? null).padStart(COL_QTY)
      );
      console.log(`  ${name} ${orig} ${scaled}`);
    }
  }
  if (nonScalable.length > 0) {
    if (scalable.length > 0) console.log();
    console.log(`  ${chalk.dim("Non-scalable (kept as-is):")}`);
    for (const item of nonScalable) {
      const name = (item.name || item.id).slice(0, COL_NAME).padEnd(COL_NAME);
      console.log(`  ${name} ${chalk.dim("\u2014")}`);
    }
  }
  console.log();
  for (const w of warnings) log.warn(w);
  if (warnings.length > 0) console.log();
}

// src/commands/scale.ts
var scale_default = defineCommand({
  meta: {
    name: "scale",
    version,
    description: "Display a before/after comparison of ingredient quantities at a given scale"
  },
  args: {
    file: {
      type: "positional",
      required: true,
      description: ".gram recipe file to scale"
    },
    scale: {
      type: "string",
      description: "Scale factor (e.g. 1.5, 2) or reference ingredient (e.g. farine=300g)"
    },
    db: {
      type: "string",
      description: "Path to ingredient database YAML"
    },
    "skip-db": {
      type: "boolean",
      description: "Skip ingredient database",
      default: false
    },
    stock: {
      type: "string",
      description: "Comma-separated @use specifiers already on hand for this scale (e.g. @bases/pate.gram,./levain.gram)"
    }
  },
  async run({ args }) {
    if (!args.scale) {
      log2.error(
        "Provide --scale <factor|ref>. Examples: --scale 2  or  --scale farine=300g"
      );
      process.exit(ExitCode.Error);
    }
    const filePath = resolve(args.file);
    const config = await loadConfig();
    const dbResult = args["skip-db"] ? null : await loadDbSafe(config, args.db);
    if (dbResult) reportRejectedIngredients(dbResult.rejected, dbResult.dbPath);
    const db = dbResult?.data ?? null;
    const stock = resolveStockFromConfig(args.stock, config);
    const s = spinner();
    s.start("Computing scaled quantities\u2026");
    try {
      const factor = await resolveScaleFactor(
        filePath,
        args.scale,
        db,
        config.language,
        config.paths
      );
      const [{ compiled: original }, { compiled: scaled }] = await Promise.all([
        runPipeline(filePath, {
          db,
          skipAnalyzer: !db,
          lang: config.language,
          paths: config.paths,
          stock
        }),
        runPipeline(filePath, {
          db,
          skipAnalyzer: !db,
          scaleFactor: factor,
          lang: config.language,
          paths: config.paths,
          stock
        })
      ]);
      s.stop("Done.");
      const items = buildScaleComparison(
        original.shopping_list,
        scaled.shopping_list
      );
      const warnings = getScaleWarnings(factor, original.metrics.totalTime);
      renderScaleResult(original.title, factor, items, warnings);
    } catch (err) {
      s.stop("Failed.");
      reportError(err);
      process.exit(ExitCode.Error);
    }
  }
});
export {
  scale_default as default
};
